        CONSTRAINT PK_ChangeSetCell     PRIMARY KEY CLUSTERED (ChangeSetRowId, OccupancyCode),
        CONSTRAINT FK_ChangeSetCell_Row FOREIGN KEY (ChangeSetRowId) REFERENCES intlgit.ChangeSetRow (ChangeSetRowId),
