-- ---------------------------------------------------------------------------
-- intlgit.usp_CompleteChangeSetRow
-- ---------------------------------------------------------------------------
CREATE OR ALTER PROCEDURE intlgit.usp_CompleteChangeSetRow
    @Reference   VARCHAR(20),
    @RowKey      VARCHAR(80),
    @Completed   BIT,
    @CompletedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ChangeSetId INT, @AppliedUtc DATETIME2(0);

    SELECT @ChangeSetId = ChangeSetId, @AppliedUtc = AppliedUtc
    FROM intlgit.ChangeSet
    WHERE Reference = @Reference;

    IF @ChangeSetId IS NULL
        THROW 60003, 'Unknown change set.', 1;

    -- An applied set is the record of what went live and does not change.
    IF @AppliedUtc IS NOT NULL
        THROW 60004, 'That change set has been applied and is now read-only.', 1;

    UPDATE intlgit.ChangeSetRow
    SET CompletedUtc = CASE WHEN @Completed = 1 THEN SYSUTCDATETIME() ELSE NULL END,
        CompletedBy  = CASE WHEN @Completed = 1 THEN @CompletedBy ELSE NULL END
    WHERE ChangeSetId = @ChangeSetId
      AND RowKey = @RowKey;

    IF @@ROWCOUNT = 0
        THROW 60005, 'That row is not in this change set.', 1;

    SELECT TotalRows, CompletedRows, IsComplete
    FROM intlgit.vw_ChangeSetProgress
    WHERE ChangeSetId = @ChangeSetId;
END
GO

-- ---------------------------------------------------------------------------
-- intlgit.usp_CompleteAllChangeSetRows
-- ---------------------------------------------------------------------------
CREATE OR ALTER PROCEDURE intlgit.usp_CompleteAllChangeSetRows
    @Reference   VARCHAR(20),
    @CompletedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ChangeSetId INT, @AppliedUtc DATETIME2(0);

    SELECT @ChangeSetId = ChangeSetId, @AppliedUtc = AppliedUtc
    FROM intlgit.ChangeSet
    WHERE Reference = @Reference;

    IF @ChangeSetId IS NULL
        THROW 60003, 'Unknown change set.', 1;

    IF @AppliedUtc IS NOT NULL
        THROW 60004, 'That change set has been applied and is now read-only.', 1;

    UPDATE intlgit.ChangeSetRow
    SET CompletedUtc = SYSUTCDATETIME(),
        CompletedBy  = @CompletedBy
    WHERE ChangeSetId = @ChangeSetId
      AND CompletedUtc IS NULL;

    SELECT TotalRows, CompletedRows, IsComplete
    FROM intlgit.vw_ChangeSetProgress
    WHERE ChangeSetId = @ChangeSetId;
END
GO

-- ---------------------------------------------------------------------------
-- intlgit.usp_MarkChangeSetApplied
-- ---------------------------------------------------------------------------
CREATE OR ALTER PROCEDURE intlgit.usp_MarkChangeSetApplied
    @Reference VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @ChangeSetId INT, @TourCode VARCHAR(10), @Note NVARCHAR(1000),
            @TotalRows INT, @AppliedUtc DATETIME2(0),
            @SubmittedByEmail NVARCHAR(200), @VersionBefore VARCHAR(10),
            @ExistingVersion VARCHAR(10);

    SELECT @ChangeSetId = cs.ChangeSetId, @TourCode = cs.TourCode,
           @Note = cs.Note, @TotalRows = cs.TotalRows, @AppliedUtc = cs.AppliedUtc,
           @SubmittedByEmail = cs.SubmittedByEmail, @VersionBefore = cs.VersionBefore,
           @ExistingVersion = cs.VersionAfter
    FROM intlgit.ChangeSet AS cs
    WHERE cs.Reference = @Reference;

    IF @ChangeSetId IS NULL
        THROW 60003, 'Unknown change set.', 1;

    /* Already applied: nothing to do, and no second promotion. Makes the
       caller safe to retry.

       The version it was given comes back with it, because the caller needs to
       report a version either way and no longer has one of its own to fall
       back on. */
    IF @AppliedUtc IS NOT NULL
    BEGIN
        SELECT AlreadyApplied = CAST(1 AS BIT), VersionAfter = @ExistingVersion;
        RETURN;
    END

    IF NOT EXISTS
    (
        SELECT 1 FROM intlgit.vw_ChangeSetProgress
        WHERE ChangeSetId = @ChangeSetId AND IsComplete = 1
    )
        THROW 60006, 'That change set still has rows outstanding.', 1;

    BEGIN TRANSACTION;

    /*
        The next version for this tour, allocated here so that two requests
        landing at once cannot take the same one.

        UPDLOCK and HOLDLOCK: the lock is held to the end of the transaction
        and covers the range this reads, so a second caller asking the same
        question waits for the stamp below rather than reading the same answer
        and allocating the same number.

        The number is parsed rather than compared as text: 'v100' sorts before
        'v99' as a string, and the padding below stops at two digits exactly as
        TourVersion.Next does.
    */
    DECLARE @Highest INT =
    (
        SELECT MAX(TRY_CAST(SUBSTRING(cs.VersionAfter, 2, 10) AS INT))
        FROM intlgit.ChangeSet AS cs WITH (UPDLOCK, HOLDLOCK)
        WHERE cs.TourCode = @TourCode
          AND cs.AppliedUtc IS NOT NULL
          AND cs.VersionAfter IS NOT NULL
    );

    -- Falling back to this request's own VersionBefore, which is what the
    -- tour was on when it was raised. 'v1' as written by the import parses
    -- here exactly as 'v01' does.
    DECLARE @Next INT =
        COALESCE(@Highest, TRY_CAST(SUBSTRING(@VersionBefore, 2, 10) AS INT), 0) + 1;

    DECLARE @VersionAfter VARCHAR(10) =
        'v' + CASE WHEN @Next < 10
                   THEN '0' + CAST(@Next AS VARCHAR(10))
                   ELSE CAST(@Next AS VARCHAR(10))
              END;

    UPDATE intlgit.ChangeSet
    SET AppliedUtc = SYSUTCDATETIME(),
        VersionAfter = @VersionAfter
    WHERE ChangeSetId = @ChangeSetId;

    /*
        And the tour is promoted, in this same transaction.

        This used to be written to an outbox (app.Outbox) and delivered to the
        Pricing web service a few seconds later, because the change sets and
        the prices lived in two different services. They now live in one
        database, so the promotion runs right here: the stamp and the new
        version either both happen or neither does. If the promotion fails, the
        set stays fully ticked but unstamped, and the application's
        UnstampedChangeSetSweeper tries again a few seconds later - the same
        "keep trying until it lands" the outbox used to give.

        The prices are the ones frozen at submission (every cell of every
        price row, unchanged ones included), exactly as the outbox payload
        carried them.
    */
    DECLARE @Prices intlgit.PriceList;

    INSERT INTO @Prices (HubCode, DepartureDate, OccupancyCode, Price)
    SELECT r.HubCode, r.DepartureDate, c.OccupancyCode, c.PublishedPrice
    FROM intlgit.ChangeSetRow AS r
        INNER JOIN intlgit.ChangeSetCell AS c
            ON c.ChangeSetRowId = r.ChangeSetRowId
    WHERE r.ChangeSetId = @ChangeSetId
      AND r.Kind = 'price';

    /*
        The version-history summary: the note the product team wrote, or
        "<n> prices revised" when there was none. TourVersionHistory.Summary is
        NVARCHAR(500), so a longer note is shortened visibly with an ellipsis
        rather than cut silently - the full note stays on the change set.
        (This was TourService.PromoteAsync / Shorten in the old Pricing API.)
    */
    DECLARE @Summary NVARCHAR(1000) =
        CASE
            WHEN @Note IS NULL
              OR PATINDEX(N'%[^ ' + NCHAR(9) + NCHAR(10) + NCHAR(13) + N']%', @Note) = 0
                THEN CAST(@TotalRows AS NVARCHAR(10)) + N' prices revised'
            ELSE @Note
        END;

    IF LEN(@Summary + N'x') - 1 > 500
        SET @Summary = LEFT(@Summary, 499) + N'…';

    EXEC intlgit.usp_PromoteVersion
        @TourCode         = @TourCode,
        @NewVersion       = @VersionAfter,
        @ChangeSetId      = @Reference,
        @Changes          = @TotalRows,
        @Summary          = @Summary,
        @SubmittedByEmail = @SubmittedByEmail,
        @Prices           = @Prices;

    COMMIT TRANSACTION;

    SELECT AlreadyApplied = CAST(0 AS BIT), VersionAfter = @VersionAfter;
END
GO

-- ---------------------------------------------------------------------------
-- intlgit.usp_ListUnstampedChangeSets
-- ---------------------------------------------------------------------------
CREATE OR ALTER PROCEDURE intlgit.usp_ListUnstampedChangeSets
AS
BEGIN
    SET NOCOUNT ON;

    SELECT cs.Reference
    FROM intlgit.ChangeSet AS cs
        INNER JOIN intlgit.vw_ChangeSetProgress AS p
            ON p.ChangeSetId = cs.ChangeSetId
    WHERE cs.AppliedUtc IS NULL
      AND p.IsComplete = 1
      AND p.TotalRows > 0
    ORDER BY cs.SubmittedUtc;
END
GO

-- =============================================================================
-- 03_Security.sql
-- =============================================================================
/*
    03_Security.sql
    One database role for the application: EXECUTE on the two area schemas,
    and nothing else. Every data access in the application is a stored
    procedure call, so the application login needs no table rights.

    Grant on SCHEMA covers procedures, functions AND the table types a
    procedure takes as a table-valued parameter.

    Put the application's SQL login (or IIS app-pool identity) into the role:
        ALTER ROLE stpl_pricing_app ADD MEMBER [YourAppLogin];

    A new pricing area (for example schema "intlfit") needs one more line:
        GRANT EXECUTE ON SCHEMA::intlfit TO stpl_pricing_app;
*/
IF NOT EXISTS (SELECT 1 FROM sys.database_principals WHERE name = 'stpl_pricing_app' AND type = 'R')
    CREATE ROLE stpl_pricing_app;
GO

GRANT EXECUTE ON SCHEMA::core    TO stpl_pricing_app;
GRANT EXECUTE ON SCHEMA::intlgit TO stpl_pricing_app;
GO

-- =============================================================================
-- 04_MasterData.sql
-- =============================================================================
/*
    04_MasterData.sql
    The reference data a brand-new Int_StplGITPricing needs to work:
      - intlgit.FareBand    adult (+ tour manager), child, infant
      - intlgit.Occupancy   the six sellable occupancies, in grid order
      - intlgit.Hub         the twelve departure hubs, Joining / Leaving first
      - core.[User]         the three starter accounts

    Safe to run more than once: rows are MERGEd by their code, and accounts
    are only created when missing (an existing password is never touched).

*/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;
GO

-- ---------------------------------------------------------------------------
-- Fare bands
-- ---------------------------------------------------------------------------
MERGE intlgit.FareBand AS target
USING (VALUES
    (1, 'adult',  N'Adult + TM'),
    (2, 'child',  N'Child'),
    (3, 'infant', N'Infant')
) AS source (FareBandId, Code, Label)
    ON source.FareBandId = target.FareBandId
WHEN MATCHED THEN UPDATE SET Code = source.Code, Label = source.Label
WHEN NOT MATCHED THEN INSERT (FareBandId, Code, Label)
    VALUES (source.FareBandId, source.Code, source.Label);
GO

-- ---------------------------------------------------------------------------
-- Occupancies. SortOrder is the column order of every price grid.
-- ---------------------------------------------------------------------------
MERGE intlgit.Occupancy AS target
USING (VALUES
    (1, 'twin',   N'Twin',   1, 1),
    (2, 'triple', N'Triple', 1, 2),
    (3, 'single', N'Single', 1, 3),
    (4, 'cwb',    N'CWB',    2, 4),
    (5, 'cnb',    N'CNB',    2, 5),
    (6, 'infant', N'Infant', 3, 6)
) AS source (OccupancyId, Code, Label, FareBandId, SortOrder)
    ON source.OccupancyId = target.OccupancyId
WHEN MATCHED THEN UPDATE SET
    Code = source.Code, Label = source.Label,
    FareBandId = source.FareBandId, SortOrder = source.SortOrder
WHEN NOT MATCHED THEN INSERT (OccupancyId, Code, Label, FareBandId, SortOrder)
    VALUES (source.OccupancyId, source.Code, source.Label, source.FareBandId, source.SortOrder);
GO

-- ---------------------------------------------------------------------------
-- Hub master, as supplied by Southern Travels.
--   'direct' (Joining / Leaving) carries no passenger airfare: its guests make
--   their own way, so its price is land + the tour manager's seat only.
--   DefaultMarkupPct is NULL on purpose - every markup is set per tour.
-- ---------------------------------------------------------------------------
MERGE intlgit.Hub AS target
USING (VALUES
    ('direct', N'Joining / Leaving', 0,   0),
    ('hyd',    N'Hyderabad',         1,  20),
    ('blr',    N'Bengaluru',         1,  30),
    ('vtz',    N'Vizag',             1,  40),
    ('ccu',    N'Kolkata',           1,  50),
    ('maa',    N'Chennai',           1,  60),
    ('del',    N'Delhi',             1,  70),
    ('bom',    N'Mumbai',            1,  80),
    ('amd',    N'Ahmedabad',         1,  90),
    ('cok',    N'Cochin',            1, 100),
    ('pnq',    N'Pune',              1, 110),
    ('nag',    N'Nagpur',            1, 120)
) AS source (Code, Name, HasPassengerAirfare, SortOrder)
    ON source.Code = target.Code
WHEN MATCHED THEN UPDATE SET
    Name = source.Name,
    HasPassengerAirfare = source.HasPassengerAirfare,
    SortOrder = source.SortOrder
WHEN NOT MATCHED THEN INSERT (Code, Name, DefaultMarkupPct, IsActive, HasPassengerAirfare, SortOrder)
    VALUES (source.Code, source.Name, NULL, 1, source.HasPassengerAirfare, source.SortOrder);
GO

-- ---------------------------------------------------------------------------
-- Starter accounts.
-- Change their passwords from "Change password" after the first sign-in.
-- ---------------------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM core.[User] WHERE Email = N'product@southerntravels.com')
    INSERT INTO core.[User] (Email, DisplayName, Role, PasswordHash)
    VALUES (N'product@southerntravels.com', N'Product Executive', 'product.executive',
            N'AQAAAAIAAYagAAAAEOccMidvOmNnJRhDcJ1VsziLOOoqTAIrfnR33UoKiueN0B7dCP705U9I9omyFG01zg==');

IF NOT EXISTS (SELECT 1 FROM core.[User] WHERE Email = N'airticketing@southerntravels.com')
    INSERT INTO core.[User] (Email, DisplayName, Role, PasswordHash)
    VALUES (N'airticketing@southerntravels.com', N'Air-ticketing Executive', 'airticketing.executive',
            N'AQAAAAIAAYagAAAAEJ02ljOMOoeLLh073/0Zm6i/ildLYTJHa1Nui3BpMau78dLgJ29KOrHqsw3FCty7TA==');

IF NOT EXISTS (SELECT 1 FROM core.[User] WHERE Email = N'techsupport@southerntravels.com')
    INSERT INTO core.[User] (Email, DisplayName, Role, PasswordHash)
    VALUES (N'techsupport@southerntravels.com', N'Tech Support', 'techsupport',
            N'AQAAAAIAAYagAAAAENWIsrewvLS38/71haNp8GKUQgmgR02N35GA/2Y57wSH4+yAcbXqkAtEYqEJjHPvew==');
GO

SELECT 'FareBand' AS [Table], COUNT(*) AS [Rows] FROM intlgit.FareBand
UNION ALL SELECT 'Occupancy', COUNT(*) FROM intlgit.Occupancy
UNION ALL SELECT 'Hub', COUNT(*) FROM intlgit.Hub
UNION ALL SELECT 'User', COUNT(*) FROM core.[User];
GO

-- =============================================================================
-- 05_TourData.sql
-- =============================================================================
/*
    05_TourData.sql
    ---------------------------------------------------------------------------
    The 23 International GIT tours: their hubs, departure dates, airfares and
    flight routings - the same tour data the old system was loaded with
    ("Sept 10th Airfare Update.xlsx" + "Active tour list.xlsx"), in schema
    intlgit. Stands alone: reads no other database.

    Needs 04_MasterData.sql first (hubs, fare bands, occupancies are looked up
    by code).

    What it holds, as in the old database:
      - 23 tours on v1, each with a cost build (pax slab) and an empty row per
        occupancy - costs are entered by the product executive
      - 266 tour-hubs incl. Joining / Leaving on every tour
      - departure dates with adult / child / infant airfare per hub and the
        airline routing behind each hub
      - strike-through % and markups blank; FX rate only on FED13, FGL10,
        FPSD6, FBA11, FBA18
      - no published prices, versions, change sets or activity yet

    Runs once: if the database already has tours it does nothing, so it can
    never load them twice.
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

IF EXISTS (SELECT 1 FROM intlgit.Tour)
BEGIN
    PRINT 'intlgit.Tour already has tours - tour data not loaded again.';
    RETURN;
END

IF NOT EXISTS (SELECT 1 FROM intlgit.Hub WHERE Code = 'direct')
   OR NOT EXISTS (SELECT 1 FROM intlgit.FareBand WHERE Code = 'adult')
BEGIN
    RAISERROR('Run 04_MasterData.sql first - hubs and fare bands are missing.', 16, 1);
    RETURN;
END
SET XACT_ABORT ON;

BEGIN TRANSACTION;


DECLARE @TourId INT, @TourHubId INT, @DepId INT;
DECLARE @AdultBandId TINYINT, @ChildBandId TINYINT, @InfantBandId TINYINT;
SELECT @AdultBandId  = FareBandId FROM intlgit.FareBand WHERE Code = 'adult';
SELECT @ChildBandId  = FareBandId FROM intlgit.FareBand WHERE Code = 'child';
SELECT @InfantBandId = FareBandId FROM intlgit.FareBand WHERE Code = 'infant';

-- -------------------------------------------------------------------------
-- FED13 · Best Of European Discovery
--    11 hubs (hyd, blr, maa, ccu, del, vtz, bom, amd, cok, nag, pnq) + direct, 6 departures
-- -------------------------------------------------------------------------
INSERT INTO intlgit.Tour (Code, Name, Region, Duration, CurrentVersion)
VALUES (N'FED13', N'Best Of European Discovery', N'Europe - UK', N'14 D / 13 N', N'v1');
SET @TourId = SCOPE_IDENTITY();

