VALUES (@TourId, 112, 112, 7, 30, NULL);

-- Costs per occupancy: a row each so the screen has a box to draw,
-- and NOTHING in it. NULL rather than 0 - no cost, no price, exactly
-- as no fare means no price. The product executive supplies these.
INSERT INTO intlgit.CostBuildOccupancy (TourId, OccupancyId, LandCostFx, PerPersonInr)
SELECT @TourId, OccupancyId, NULL, NULL FROM intlgit.Occupancy;

SET @TourHubId = NULL;
INSERT INTO intlgit.TourHub (TourId, HubId, MarkupPct, IsActive)
SELECT @TourId, HubId, DefaultMarkupPct, 1 FROM intlgit.Hub WHERE Code = 'hyd';
SET @TourHubId = SCOPE_IDENTITY();
INSERT INTO intlgit.TourDeparture (TourHubId, DepartureDate, IsActive) VALUES (@TourHubId, '2026-10-02', 1);
SET @DepId = SCOPE_IDENTITY();
INSERT INTO intlgit.DepartureFare (TourId, TourDepartureId, FareBandId, Amount) VALUES (@TourId, @DepId, @AdultBandId, 78000.00);
INSERT INTO intlgit.DepartureFare (TourId, TourDepartureId, FareBandId, Amount) VALUES (@TourId, @DepId, @ChildBandId, 69000.00);
INSERT INTO intlgit.DepartureFare (TourId, TourDepartureId, FareBandId, Amount) VALUES (@TourId, @DepId, @InfantBandId, 12500.00);
INSERT INTO intlgit.DepartureFlight (TourDepartureId, Details, ModifiedBy) VALUES (@DepId, N'EY277 HYD AUH 2100 2320
EY11 AUH LHR 0205 0645
EY86 FCO AUH 1020 1825
EY274 AUH HYD 2155 0315+1', N'Sept 10th airfare update');
INSERT INTO intlgit.TourDeparture (TourHubId, DepartureDate, IsActive) VALUES (@TourHubId, '2026-11-06', 1);
SET @DepId = SCOPE_IDENTITY();
INSERT INTO intlgit.DepartureFare (TourId, TourDepartureId, FareBandId, Amount) VALUES (@TourId, @DepId, @AdultBandId, 75000.00);
INSERT INTO intlgit.DepartureFare (TourId, TourDepartureId, FareBandId, Amount) VALUES (@TourId, @DepId, @ChildBandId, 69000.00);
INSERT INTO intlgit.DepartureFare (TourId, TourDepartureId, FareBandId, Amount) VALUES (@TourId, @DepId, @InfantBandId, 12500.00);
INSERT INTO intlgit.DepartureFlight (TourDepartureId, Details, ModifiedBy) VALUES (@DepId, N'EY277 HYD AUH 2100 2320
EY11 AUH LHR 0205 0645
EY86 FCO AUH 1020 1825
EY274 AUH HYD 2155 0315+1', N'Sept 10th airfare update');
