-- ---------------------------------------------------------------------------
-- Later corrections, applied exactly as the old database received them
-- ---------------------------------------------------------------------------

-- The guessed figures are blanked (old migration 0074): no strike-through %,
-- no markup, and an FX rate only on the five tours whose rate was confirmed.
UPDATE intlgit.CostBuild SET StrikePct = NULL;
UPDATE intlgit.TourHub   SET MarkupPct = NULL;
UPDATE cb
SET cb.FxRate = NULL, cb.PreviousFxRate = NULL
FROM intlgit.CostBuild AS cb
    INNER JOIN intlgit.Tour AS t ON t.TourId = cb.TourId
WHERE t.Code NOT IN ('FED13', 'FGL10', 'FPSD6', 'FBA11', 'FBA18');

-- Joining / Leaving carries every upcoming date its tour departs on from a
-- passenger hub (old migration 0085).
INSERT INTO intlgit.TourDeparture (TourHubId, DepartureDate, IsActive)
SELECT DISTINCT dth.TourHubId, td.DepartureDate, CAST(1 AS BIT)
FROM intlgit.TourDeparture AS td
    INNER JOIN intlgit.TourHub AS th ON th.TourHubId = td.TourHubId
    INNER JOIN intlgit.Hub AS h ON h.HubId = th.HubId
    INNER JOIN intlgit.TourHub AS dth ON dth.TourId = th.TourId
    INNER JOIN intlgit.Hub AS dh ON dh.HubId = dth.HubId AND dh.HasPassengerAirfare = 0
WHERE h.HasPassengerAirfare = 1
  AND th.IsActive = 1
  AND td.IsActive = 1
  AND td.DepartureDate >= CAST(SYSUTCDATETIME() AS DATE)
  AND NOT EXISTS
  (
      SELECT 1 FROM intlgit.TourDeparture AS existing
      WHERE existing.TourHubId = dth.TourHubId
        AND existing.DepartureDate = td.DepartureDate
  );

COMMIT TRANSACTION;

GO

SELECT
    (SELECT COUNT(*) FROM intlgit.Tour)            AS Tours,
    (SELECT COUNT(*) FROM intlgit.TourHub)         AS TourHubs,
    (SELECT COUNT(*) FROM intlgit.TourDeparture)   AS Departures,
    (SELECT COUNT(*) FROM intlgit.DepartureFare)   AS Fares,
    (SELECT COUNT(*) FROM intlgit.DepartureFlight) AS FlightRoutings;
GO
